# Exact E8 Cartan matrix; branch lengths 1,2,4 from vertex0.
G=[[F(2*(a==b)) for b in range(8)] for a in range(8)]
for a,b in [(0,1),(0,2),(2,3),(0,4),(4,5),(5,6),(6,7)]:G[a][b]=G[b][a]=F(-1)
A=[G[j][:]+[F(j==k) for k in range(8)] for j in range(8)];piv=[];det=F(1)
for j in range(8):
 v=A[j][j];assert v>0;piv.append(str(v));det*=v;A[j]=[x/v for x in A[j]]
 for k in range(8):
  if k!=j:
   v=A[k][j];A[k]=[a-v*b for a,b in zip(A[k],A[j])]
inv=[a[8:] for a in A];assert det==1;assert all(v.denominator==1 for a in inv for v in a);assert all(inv[j][j]%2==0 for j in range(8))
save('bounded-checks.json',{'id':397337,'executed':True,'arithmetic':'fractions.Fraction; 8x8 exact Gauss-Jordan with positive pivots','gram':[[int(v) for v in a] for a in G],'pivots':piv,'determinant':str(det),'inverse':[[int(v) for v in a] for a in inv],'inverse_even_diagonal':True,'proof':'If an isometric Z^n embedding existed, the images of a basis form an integer 8xn matrix B with BB^T=G. Each nonzero column v has v^T G^-1 v a positive even integer, hence >=2. Rank(B)=8 forces at least8 nonzero columns, so trace(G^-1 BB^T)>=16, while trace(I8)=8. Contradiction. Positive pivots certify G positive definite; symmetric integral inverse with even diagonal certifies even integral values.','credit':0,'objection':'Classical even-unimodular E8 obstruction and short standard Gram adaptation; no new-to-literature claim, current registry unavailable.','planned_calculations':[]})
